	testExpression(exp) {
		if(exp.indexOf(" ") > -1) {
			return app_ExpressionTester.testWithGlue(app_StringUtil.splitQuoted(exp),0,$bind(this,this.expandExpressionLhs));
		}
		let re = new EReg("([^ <>!=]+)\\s*((?:has|!has|[<>!=]+))\\s*([^ <>!=]+)","i");
		if(!re.match(exp)) {
			return false;
		}
		let lhs = re.matched(1);
		let op = re.matched(2);
		let rhs = re.matched(3);
		if(lhs != "PASSTHROUGH") {
			lhs = this.expandExpressionLhs(lhs);
			if(lhs == null) {
				lhs = "";
			}
		}
		lhs = lhs.toLowerCase();
		rhs = rhs.toLowerCase();
		switch(op) {
		case "!=":
			return lhs != rhs;
		case "!has":
			return lhs.indexOf(rhs) < 0;
		case "<":
			let v = Std.parseInt(lhs);
			let v1 = Std.parseInt(rhs);
			return (v == null ? 0 : v) < (v1 == null ? 0 : v1);
		case "<=":
			let v2 = Std.parseInt(lhs);
			let v3 = Std.parseInt(rhs);
			return (v2 == null ? 0 : v2) <= (v3 == null ? 0 : v3);
		case "==":
			return lhs == rhs;
		case ">":
			let v4 = Std.parseInt(rhs);
			let v5 = Std.parseInt(lhs);
			return (v4 == null ? 0 : v4) < (v5 == null ? 0 : v5);
		case ">=":
			let v6 = Std.parseInt(rhs);
			let v7 = Std.parseInt(lhs);
			return (v6 == null ? 0 : v6) <= (v7 == null ? 0 : v7);
		case "has":
			return lhs.indexOf(rhs) > -1;
		default:
			return false;
		}
	}
	expandExpressionLhs(lhs) {
		let v = this.getFactSetForPath(lhs).getValue(lhs);
		if(v == null) {
			return "";
		} else {
			return v.text;
		}
	}
